<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Services\{SettingsRegistry,SettingsService}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class SettingsController extends Controller { public function index(SettingsService $service):View{return view('admin.settings.index',['groups'=>SettingsRegistry::groups(),'registry'=>SettingsRegistry::all(),'values'=>$service->all()]);} public function update(Request $request,string $group,SettingsService $service):RedirectResponse{$fields=collect(SettingsRegistry::all())->filter(fn($m)=>$m['group']===$group);$rules=[];foreach($fields as $key=>$meta)$rules[substr($key,strlen($group)+1)]=$meta['rules'];$service->update($group,$request->validate($rules));return back()->with('status',ucfirst($group).' settings updated.');} }
